import { Page, Locator } from '@playwright/test';

export class SearchResultsPage {
    private readonly page: Page;

    // Locators
    private readonly headingSearch: Locator;
    private readonly lnkProductNames: Locator;

    constructor(page: Page) {
        this.page = page;

        // Initialize locators with CSS selectors
        this.headingSearch = page.getByRole('heading', { name: /^Search - / });
        this.lnkProductNames = page.locator('.product-thumb h4 a');
    }

    /**
     * Verifies the search results page is displayed
     * @returns Promise<boolean> - true if the "Search - <keyword>" heading is displayed
     */
    async isSearchResultsPageExists(): Promise<boolean> {
        try {
            await this.headingSearch.waitFor({ state: 'visible' });
            return true;
        } catch (error) {
            console.log(`Error checking search results page: ${error}`);
            return false;
        }
    }

    /**
     * Checks whether a product with the exact name appears in the results
     * @param productName - Exact product name
     * @returns Promise<boolean> - true if the product is listed
     */
    async isProductExist(productName: string): Promise<boolean> {
        try {
            await this.lnkProductNames.getByText(productName, { exact: true }).waitFor({ state: 'visible' });
            return true;
        } catch (error) {
            console.log(`Error checking product in results: ${error}`);
            return false;
        }
    }

    /**
     * Gets the names of all products in the results
     * @returns Promise<string[]> - Product names
     */
    async getProductNames(): Promise<string[]> {
        await this.lnkProductNames.first().waitFor({ state: 'visible' });
        return (await this.lnkProductNames.allTextContents()).map((name) => name.trim());
    }

    /**
     * Opens the product details page of the given product
     * @param productName - Exact product name
     */
    async selectProduct(productName: string): Promise<void> {
        await this.lnkProductNames.getByText(productName, { exact: true }).click();
    }
}
